import (
	"fmt"
	"strconv"
)

func parseCount(input string) (int, error) {
	n, err := strconv.Atoi(input)
	if err != nil {
		return 0, fmt.Errorf("invalid count %q: %w", input, err)
	}
	return n, nil
}

func main() {
	for _, input := range []string{"0", "bad"} {
		n, err := parseCount(input)
		fmt.Printf("input=%q count=%d err=%v\n", input, n, err)
	}
}

