	}
	return n, nil
}

func TestParseCount(t *testing.T) {
	if n, err := parseCount("0"); err != nil || n != 0 {
		t.Fatalf("valid zero: n=%d err=%v", n, err)
	}
	if _, err := parseCount("bad"); err == nil {
		t.Fatal("invalid input should return an error")
	}
}

